class GateFailure(RuntimeError):
    """A merge-gate refusal with an operator-facing explanation."""


@dataclass(frozen=True)
class GateExpectation:
    """The immutable PR comparison accepted for this merge invocation."""

    branch: str
    base: str
    head_sha: str
    base_sha: str


@dataclass(frozen=True)
class GateSnapshot:
