    review_lock.require_owned()
    pull = client.get_pull(number)
    identity = require_open_mergeable(pull, number)
    _require_expected(identity, expected)
    local_head, worktree = exact_local_head(root, expected.branch)
    local_base = exact_local_base(root, expected.base)
    if local_head != expected.head_sha or local_base != expected.base_sha:
        raise GateFailure(
            "local head/base do not match the immutable GitHub comparison "
            f"(local_head={local_head}, local_base={local_base})"
        )

    ci = require_ci(client, number, expected.head_sha, expected.base_sha)
    fix_lock.require_owned(reject_cancel=True)
    commits = client.pull_commits(number)
    iterations = fix_iteration_count(commits)
    if iterations > cap:
        raise GateFailure(
            f"fix iteration count {iterations} exceeds configured cap {cap}"
        )
    if adjudicated:
        require_adjudication(client, pull, number, expected.head_sha)

    # Rebind the comparison after all potentially paginated reads. The review
    # check is last so a same-head adverse review introduced during evaluation
    # cannot be hidden by an earlier clean-ledger read.
    final_pull = client.get_pull(number)
    final_identity = require_open_mergeable(final_pull, number)
    _require_expected(final_identity, expected)
    final_local_head, final_worktree = exact_local_head(root, expected.branch)
    final_local_base = exact_local_base(root, expected.base)
    if (
        final_local_head != expected.head_sha
        or final_local_base != expected.base_sha
        or final_worktree.resolve() != worktree.resolve()
    ):
        raise GateFailure("local head/base/worktree changed during gate evaluation")
    fix_lock.require_owned(reject_cancel=True)
    review = require_review(
        client, number, expected.head_sha, expected.base_sha
    )
    attested_worktree = Path(review.attestation.lanes[0].worktree).resolve()
    if attested_worktree != worktree.resolve():
        raise GateFailure(
            "review session telemetry is bound to a different feature worktree"
        )
    review_lock.require_owned()
    fix_lock.require_owned(reject_cancel=True)
    return GateSnapshot(
        pull=final_pull,
        identity=final_identity,
        worktree=worktree,
        ci=ci,
        review=review,
        iterations=iterations,
    )


def fast_forward_base(root: Path, base: str) -> None:
    git(
        root,
        "fetch",
        "--no-tags",
        "github",
        f"refs/heads/{base}:refs/remotes/github/{base}",
    )
    worktree = branch_worktree(root, base)
    if worktree is None:
        raise GateFailure(
            f"GitHub merged the PR, but no local checkout of base branch {base!r} exists"
        )
    if git(worktree, "status", "--porcelain"):
        raise GateFailure(
            f"GitHub merged the PR, but base worktree {worktree} is dirty; "
            "it was not advanced"
        )
    git(worktree, "merge", "--ff-only", f"refs/remotes/github/{base}")


def cleanup_feature(root: Path, branch: str, worktree: Path, merge_sha: str) -> None:
    if git(worktree, "status", "--porcelain"):
        raise GateFailure(
            f"PR merged, but feature worktree {worktree} is dirty; cleanup was skipped"

def pull_commits(self, number: int) -> list[dict[str, Any]]:
    pull = self.get_pull(number)
    expected = pull.get("commits")
    if not isinstance(expected, int) or expected < 0:
        raise GitHubError(
            f"PR #{number} does not report a trustworthy commit count"
        )
    if expected > 250:
        raise GitHubError(
            f"PR #{number} reports {expected} commits, beyond GitHub's "
            "250-commit PR endpoint cap; complete fix history cannot be proven"
        )
    rows = self.paginate(f"/repos/{self.repo}/pulls/{number}/commits")
    if len(rows) != expected:
        raise GitHubError(
            f"PR #{number} reports {expected} commits but the endpoint returned "
            f"{len(rows)}; refusing incomplete history"
        )
    return rows

def statuses(self, sha: str) -> list[dict[str, Any]]:
    sha = normalize_sha(sha)
    return self.paginate(f"/repos/{self.repo}/commits/{sha}/statuses")

def latest_statuses(self, sha: str) -> dict[str, dict[str, Any]]:
    sha = normalize_sha(sha)
    result: dict[str, dict[str, Any]] = {}
    rows = self.statuses(sha)
    rows.sort(
        key=lambda row: (
            str(row.get("created_at") or ""),
            int(row.get("id") or 0),
        ),
        reverse=True,
    )
    for row in rows:
        row_sha = str(row.get("sha") or "")
        if not _SHA_RE.fullmatch(row_sha) or row_sha.lower() != sha:
            continue
        context = str(row.get("context") or "").casefold()
        if context and context not in result:
            result[context] = row
    return result

@staticmethod
def _latest(rows: Iterable[dict[str, Any]], timestamp: str) -> dict[str, Any]:
    candidates = list(rows)
    if not candidates:
        raise GitHubError("no matching authoritative publication was found")
    candidates.sort(
        key=lambda row: (
            str(row.get(timestamp) or row.get("created_at") or ""),
            int(row.get("id") or 0),
        ),
        reverse=True,
    )
    return candidates[0]

def ci_evidence(
    self, number: int, sha: str, base_sha: str | None = None
) -> CIManifestEvidence:
    """Parse a complete manifest and bind every status to its exact run."""
    number = normalize_number(number, kind="PR number")
    sha = normalize_sha(sha)
    expected_base = normalize_sha(base_sha, kind="pull-request base SHA") if base_sha else None
    matches: list[dict[str, Any]] = []
    for row in self.comments(number):
        body = str(row.get("body") or "")
        markers = _CI_MARKER_RE.findall(body)
        if not any(int(pr) == number and head.lower() == sha for pr, head, _ in markers):
            continue
        matches.append(row)
    row = self._latest(matches, "created_at")
    body = str(row.get("body") or "")
    if body.count("<!-- mipstarre:ci-manifest ") != 1:
        raise GitHubError("latest exact-head CI manifest has ambiguous markers")
    marker_match = _CI_MARKER_RE.search(body)
    if marker_match is None:
        raise GitHubError("latest exact-head CI manifest has a malformed marker")
    marker = marker_match.group(0)
    if body[marker_match.start() :] not in {marker, marker + "\n"}:
        raise GitHubError("latest exact-head CI manifest marker is not the final line")
    marker_run = marker_match.group(3)
    fenced = re.search(r"```json\s*\n(.*?)\n```", body, re.DOTALL)
    if not fenced or body.count("```json") != 1:
        raise GitHubError("latest exact-head CI comment has no JSON manifest fence")
    try:
        manifest = json.loads(fenced.group(1))
    except json.JSONDecodeError as exc:
        raise GitHubError(f"latest exact-head CI manifest is invalid JSON: {exc}") from exc
    if not isinstance(manifest, dict):
        raise GitHubError("latest exact-head CI manifest is not an object")
    manifest_head = normalize_sha(
        str(manifest.get("head_sha") or ""), kind="CI manifest head SHA"
    )
    manifest_base = normalize_sha(
        str(manifest.get("base_sha") or ""), kind="CI manifest base SHA"
    )
    if manifest_head != sha:
        raise GitHubError("latest CI manifest does not record the exact requested head")
    if expected_base is not None and manifest_base != expected_base:
        raise GitHubError("latest CI manifest does not record the exact requested base")
